class Solution:
    def subarraysWithMoreOnesThanZeroes(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        ans = 0
        for i in range(len(nums)):
            bal = 0
            for j in range(i, len(nums)):
                bal += 1 if nums[j] == 1 else -1
                if bal > 0:
                    ans = (ans + 1) % MOD
        return ans

