    int subarraysWithMoreOnesThanZeroes(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        long long ans = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            int bal = 0;
            for (int j = i; j < (int)nums.size(); j++) {
                bal += nums[j] == 1 ? 1 : -1;
                if (bal > 0) ans++;
            }
        }
        return (int) (ans % MOD);
    }
