class Solution {
public:
    int subarraysWithMoreOnesThanZeroes(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size(), m = 2 * n + 2;
        vector<int> tree(m + 1, 0);
        auto update = [&](int i) {
            for (i++; i <= m; i += i & (-i)) tree[i]++;
        };
        auto query = [&](int i) {
            int res = 0;
            for (i++; i > 0; i -= i & (-i)) res += tree[i];
            return res;
        };
        update(n);
        int pref = 0, ans = 0;
        for (int x : nums) {
            pref += x == 1 ? 1 : -1;
            ans = (ans + query(pref + n - 1)) % MOD;
            update(pref + n);
        }
        return ans;
    }
};

