class Solution {
    public int subarraysWithMoreOnesThanZeroes(int[] nums) {
        final int MOD = 1_000_000_007;
        int n = nums.length, m = 2 * n + 2;
        int[] tree = new int[m + 1];
        add(tree, n, m);
        int pref = 0;
        long ans = 0;
        for (int x : nums) {
            pref += x == 1 ? 1 : -1;
            ans = (ans + sum(tree, pref + n - 1)) % MOD;
            add(tree, pref + n, m);
        }
        return (int) ans;
    }

    private void add(int[] tree, int i, int m) {
        for (i++; i <= m; i += i & (-i)) tree[i]++;
    }

    private int sum(int[] tree, int i) {
        int res = 0;
        for (i++; i > 0; i -= i & (-i)) res += tree[i];
        return res;
    }
}

