var subarraysWithMoreOnesThanZeroes = function(nums) {
    const MOD = 1e9 + 7;
    const n = nums.length, m = 2 * n + 2;
    const tree = new Array(m + 1).fill(0);
    const add = i => { for (i++; i <= m; i += i & (-i)) tree[i]++; };
    const query = i => { let r = 0; for (i++; i > 0; i -= i & (-i)) r += tree[i]; return r; };
    add(n);
    let pref = 0, ans = 0;
    for (const x of nums) {
        pref += x === 1 ? 1 : -1;
        ans = (ans + query(pref + n - 1)) % MOD;
        add(pref + n);
    }
    return ans;
};
